CREATE TABLE "Hashtag" ("id" TEXT NOT NULL,"tag" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Hashtag_pkey" PRIMARY KEY ("id"));CREATE UNIQUE INDEX "Hashtag_tag_key" ON "Hashtag"("tag");CREATE TABLE "PostHashtag" ("postId" TEXT NOT NULL,"hashtagId" TEXT NOT NULL,CONSTRAINT "PostHashtag_pkey" PRIMARY KEY ("postId","hashtagId"));CREATE INDEX "PostHashtag_hashtagId_idx" ON "PostHashtag"("hashtagId");ALTER TABLE "PostHashtag" ADD CONSTRAINT "PostHashtag_postId_fkey" FOREIGN KEY ("postId") REFERENCES "Post"("id") ON DELETE CASCADE ON UPDATE CASCADE;ALTER TABLE "PostHashtag" ADD CONSTRAINT "PostHashtag_hashtagId_fkey" FOREIGN KEY ("hashtagId") REFERENCES "Hashtag"("id") ON DELETE CASCADE ON UPDATE CASCADE;